/**
 * Process markdown files to assign names to placeholders before AI processing
 */
async function preprocessPlaceholders(changedFiles) {
    if (!changedFiles || changedFiles.length === 0) {
        console.log('ℹ️  No files to process for placeholders');
        return [];
    }

    console.log('🎯 Pre-processing placeholders in markdown files...');
    const processedFiles = [];
    
    for (const filePath of changedFiles) {
        if (filePath.endsWith('.md') || filePath.endsWith('.mdx')) {
            try {
                console.log(`📝 Processing placeholders in: ${filePath}`);
                const result = await processMarkdownFile(filePath);
                
                // Set the current markdown file path for image reference
                if (aiUtils) {
                    console.log(`📄 Setting current markdown path for AIUtilsEnhanced: ${filePath}`);
                    aiUtils.setCurrentMdFilePath(filePath);
                }
                
                if (result.placeholderCount > 0) {
                    const imageNames = extractImageNamesFromPlaceholders(result.updatedContent);
                    console.log(`🖼️  Assigned image names:`, imageNames);
                    
                    processedFiles.push({
                        filePath,
                        imageNames,
                        placeholderCount: result.placeholderCount
                    });
                } else {
                    console.log(`ℹ️  No placeholders found in ${filePath}`);
                }
            } catch (error) {
                console.error(`❌ Error processing placeholders in ${filePath}:`, error.message);
            }
        }
    }
    
    return processedFiles;
}

/**
 * Post-process to replace placeholders with actual image references
 */
async function postprocessPlaceholders(processedFiles) {
    if (!processedFiles || processedFiles.length === 0) {
        console.log('ℹ️  No files to post-process');
        return;
    }

    console.log('🔄 Post-processing: Replacing placeholders with image references...');
    
    for (const fileInfo of processedFiles) {
        const { fileURLToPath } = await import('node:url');
        const path = await import('node:path');
        const fs = await import('node:fs');
        
        const mdDir = path.dirname(fileInfo.filePath);
        const imgDir = path.join(mdDir, 'img');
        
        console.log(`📁 Checking for generated images in: ${imgDir}`);
        
        for (const imageName of fileInfo.imageNames) {
            const imagePath = path.join(imgDir, imageName);
            try {
                await fs.promises.access(imagePath);
                console.log(`✅ Found generated image: ${imageName}`);
                await replacePlaceholderWithImage(fileInfo.filePath, imageName);
            } catch {
                console.warn(`⚠️  Image not generated: ${imageName} (expected at: ${imagePath})`);
            }
        }
    }
    
    console.log('✅ Placeholder post-processing completed');
}

